// Plan: LinkedIn Guardian build series, one episode at a time (max 1 draft per run)
const TZ = 'Europe/Dublin';
const MAX_OPEN_DRAFTS = 2;
const IMAGES = 'https://drive.google.com/drive/folders/YOUR_GOOGLE_ID-';
const PILLAR = 'Guardian series';

// EDIT ME: episodes in order. "facts" = what really happened; the drafter may only use these + PROJECT FACTS.
const EPISODES = [
  { topic: 'Why I started building LinkedIn Guardian',
    facts: 'Job hunting in Ireland for Business Analyst, Data Analyst and Associate PM roles meant checking many job sites and alert emails by hand. I wanted one system that finds jobs, scores them against my CV and drafts outreach, but never sends anything without my approval.',
    image: 'Screenshot: the Guardian Console dashboard tab in Google Sheets.' },
  { topic: 'The architecture: n8n workflows, Google Sheets and Slack',
    facts: 'Guardian is 8 n8n workflows: Error Alerter, Voice Drafter, Brain, Job Intake, Job Matcher, Connection Assistant, Publisher and Content Studio. Google Sheets is the console and database. Slack is where I approve things.',
    image: 'Screenshot: the n8n folder listing all Guardian workflows (hide any emails).' },
  { topic: 'Job Intake: reading job-alert emails instead of scraping',
    facts: 'Job Intake pulls from company job boards (Greenhouse, Lever, Ashby), Jooble, Google Jobs, and the job-alert emails LinkedIn, Indeed, IrishJobs and Jobs.ie already send me. An LLM extracts each job from the email as JSON, and code checks that every title really appears in the email.',
    image: 'Screenshot: the 04 Job Intake canvas, both paths visible.' },
  { topic: 'The bug that made every Indeed link the same',
    facts: 'My email cleaner cut every link at the "?" to remove tracking. Indeed keeps the job ID in that part, so every Indeed job got the same dead link. The fix: read the jk parameter and rebuild a clean viewjob link.',
    image: 'Screenshot: the Clean Email code node, zoomed on the URL function.' },
  { topic: 'One title filter for every job source',
    facts: '"Graduate Mechanical Engineer" slipped into my data-analyst pipeline because the word "graduate" matched. I replaced the per-source checks with one shared Title Filter: a core-role list and a block list, applied to every source.',
    image: 'Screenshot: the Title Filter code node.' },
  { topic: 'Scoring every job 0-100 against my CV',
    facts: 'Job Matcher reads my Master CV live from Google Docs. Score = location (3-15) + seniority (0-25, parsed from title and years of experience) + skills (0-40, judged by Gemini) + domain (0-20). Strong fits ping me in Slack.',
    image: 'Screenshot: the JobsData tab with the fit_score column visible (hide URLs if needed).' },
  { topic: 'Deduplicating against the sheet, not the workflow memory',
    facts: 'The same job arrives from several sources. I dedupe against the JobsData sheet itself, so a failed run never loses or repeats jobs. Jooble job IDs were larger than JavaScript can hold exactly, so I take the ID from the URL instead.',
    image: 'Screenshot: the Dedupe and Keep Only New nodes on the canvas.' },
  { topic: 'The Voice Drafter: 3 drafts and a rule-based lint',
    facts: 'Every draft is written 3 ways, then a code-only lint checks it: no em dashes, no AI buzzwords, no numbers that are not in my fact list, correct length. If nothing passes, it retries once with the exact flags.',
    image: 'Screenshot: the 02 Voice Drafter canvas.' },
  { topic: 'The day my agent invented facts about me',
    facts: 'An early draft claimed a Power BI report and jobs delivered to my LinkedIn inbox. Neither existed. I added a written list of true project facts to the prompt and a false-claim check to the lint.',
    image: 'Screenshot: the ContentQueue row showing the Rejected draft and my feedback.' },
  { topic: 'The Brain: a chat agent that kept calling its own tool',
    facts: 'The Brain is an n8n AI agent with tools that read jobs, save memory and draft text. It called the drafting tool again and again, and the free Groq model hit its 8,000 tokens-per-minute limit. The fix: a clearer tool description, a cap on agent iterations, and one model per job.',
    image: 'Screenshot: the 03 Brain canvas with its tools.' },
  { topic: 'Living on free tiers: pacing instead of paying',
    facts: 'Free API tiers limit tokens per minute per model. Instead of paying, I give each job its own model and pace calls with a Loop and a Wait node, one email at a time.',
    image: 'Screenshot: the Loop Over Items and Wait nodes in Job Intake.' },
  { topic: 'Connection Assistant: drafts, but I press send',
    facts: 'Twice a day it picks my strongest job matches, drafts a short connection note and builds LinkedIn people-search links for the recruiter and hiring manager. I find the person and send it myself.',
    image: 'Screenshot: the ConnectionLog tab with a Pending row (hide names).' },
  { topic: 'Publisher: nothing goes live without Approved',
    facts: 'The Publisher checks the ContentQueue every 15 minutes and posts only rows I marked Approved, through the official LinkedIn API, at most one post per 20 hours.',
    image: 'Screenshot: the 07 Publisher canvas.' },
  { topic: 'Content Studio: this series writes itself, I edit it',
    facts: 'Content Studio drafts the next episode every hour if fewer than 2 drafts are waiting. When I reject a draft and write why, it rewrites it using my reason and logs the feedback.',
    image: 'Screenshot: the 08 Content Studio canvas.' },
  { topic: 'Knowing when it breaks: Error Alerter',
    facts: 'Every workflow sends failures to one Error Alerter, which posts to Slack and logs to the sheet, so a silent failure cannot hide.',
    image: 'Screenshot: a Slack error alert (hide any keys).' },
];

const rows = $('Read ContentQueue').all().map(i => i.json).filter(r => r.post_id);
const fb = $('Read Feedback').all().map(i => i.json)
  .filter(r => String(r.item_type || '').toLowerCase() === 'post' && r.reason);
const lessons = fb.slice(-8).map(r => `- ${r.reason}`).join('\n');

const st = r => String(r.status || '').trim().toLowerCase();
const low = s => String(s || '').trim().toLowerCase();
const used = new Set(rows.filter(r => st(r) !== 'rejected').map(r => low(r.topic)));
const newId = () => `p-${$now.setZone(TZ).toFormat('yyyyMMddHHmmss')}`;
const epIndex = topic => EPISODES.findIndex(e => low(e.topic) === low(topic));
const nextEpisode = () => EPISODES.findIndex(e => !used.has(low(e.topic)));

const buildContext = (i, note) => [
  `SERIES: "Building LinkedIn Guardian", episode ${i + 1} of ${EPISODES.length}. Mention "Episode ${i + 1}" in the first 2 lines.`,
  `TOPIC: ${EPISODES[i].topic}`,
  `WHAT REALLY HAPPENED (use only this and PROJECT FACTS): ${EPISODES[i].facts}`,
  note || '',
  'RULES FOR THIS SERIES: write only about building LinkedIn Guardian. Do NOT mention past employers, past jobs or any MY FACTS item. One concrete detail, one lesson, simple English.',
  'AUDIENCE: hiring managers, analysts, product people and automation builders in Ireland.',
  lessons ? `PAST REJECTION REASONS FROM TUSHAR (do not repeat these mistakes):\n${lessons}` : '',
].filter(Boolean).join('\n\n');

const plan = (mode, i, note, parent) => [{ json: {
  mode, post_id: newId(), pillar: PILLAR, topic: EPISODES[i].topic,
  image_brief: EPISODES[i].image, images_folder: IMAGES,
  parent_post_id: parent ? parent.post_id : '',
  parent_reason: parent ? String(parent.your_feedback || '').trim() : '',
  context: buildContext(i, note),
} }];

// 1. A rejected post always gets handled first
const rejected = rows.find(r => st(r) === 'rejected');
if (rejected) {
  const reason = String(rejected.your_feedback || '').trim() || '(no reason given, so change the angle and the hook completely)';
  let i = epIndex(rejected.topic);
  if (i === -1) {
    // not part of the series: replace it with the next episode
    i = nextEpisode();
    if (i === -1) i = 0;
    return plan('redraft', i, `Tushar rejected an earlier post. His reason: ${reason}`, rejected);
  }
  const note = `REWRITE. Tushar rejected this earlier draft of the episode:\n<<<\n${String(rejected.draft || '').slice(0, 1500)}\n>>>\nHis reason: ${reason}\nWrite a NEW version. Do not reuse its hook, structure or examples.`;
  return plan('redraft', i, note, rejected);
}

// 2. Otherwise keep the queue topped up with the next episode
if (rows.filter(r => st(r) === 'draft').length >= MAX_OPEN_DRAFTS) return [];
const i = nextEpisode();
if (i === -1) return [];   // series finished: add more EPISODES above
return plan('new', i, '', null);

// Turn the Voice Drafter result into a ContentQueue row (accepts any 02 output shape)
const plan = $('Plan').first().json;
const r = $input.first().json;
const pick = (...xs) => xs.find(x => typeof x === 'string' && x.trim());
const bestObj = (r.best && typeof r.best === 'object') ? r.best : {};
const text = String(pick(bestObj.text, r.best_draft?.text, r.best_draft, r.variants?.[0]?.text, r.text, r.output) || '').trim();
if (!text) throw new Error('Voice Drafter returned no draft. Keys received: ' + Object.keys(r).join(', '));
const alts = (r.variants || []).map(v => v.text).filter(t => t && t.trim() !== text).join('\n---\n');
const flags = bestObj.flags || r.lint_flags || [];
return [{ json: {
  post_id: plan.post_id,
  pillar: plan.pillar,
  topic: plan.topic,
  scheduled_for: '',
  draft: text,
  chars: text.length,
  alt_drafts: alts.slice(0, 40000),
  lint_flags: Array.isArray(flags) ? flags.join('; ') : String(flags),
  status: 'Draft',
  approved_at: '',
  posted_at: '',
  linkedin_post_urn: '',
  your_feedback: '',
  image_brief: plan.image_brief,
  image_file: '',
} }];

