// Continue only when this run replaced a rejected post
const p = $('Plan').first().json;
if (p.mode !== 'redraft' || !p.parent_post_id) return [];
return [{ json: { post_id: p.parent_post_id, status: 'Redrafted' } }];

// Log the rejection so the Brain and the Studio learn from it
const p = $('Plan').first().json;
return [{ json: {
  ts: $now.setZone('Europe/Dublin').toISO(),
  item_type: 'post',
  item_id: p.parent_post_id,
  verdict: 'Rejected',
  reason: p.parent_reason || '(no reason given)',
} }];
